def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    slots = int(supply / WATER_REQ)
    if slots < 0:
        slots = 0

    prev_bids = []
    opp_pressures = []
    desperate_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        pressure = 0.0
        if bid is not None:
            pressure += float(bid)
        pressure += max(0, 4 - opp.get('hp', 0)) * 8.0
        pressure += opp.get('no_water_days', 0) * 10.0
        if opp.get('budget', 0) > budget:
            pressure += 4.0
        opp_pressures.append(pressure)
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    max_pressure = max(opp_pressures) if opp_pressures else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    contested = False
    if slots <= 1:
        contested = True
    if desperate_count >= max(1, slots):
        contested = True
    if highest_prev >= 110:
        contested = True

    if not alive_opponents:
        bid = 18.0 if urgency == 0 else 42.0
    elif urgency >= 5:
        bid = max(0.95 * DAILY_SALARY, highest_prev + 2.5, avg_prev + 4.0)
    elif urgency >= 3:
        if contested:
            bid = max(0.82 * DAILY_SALARY, highest_prev + 1.5)
        else:
            bid = max(0.62 * DAILY_SALARY, avg_prev * 0.7 + 6.0)
    elif urgency >= 1:
        if slots >= 2 and highest_prev >= 95:
            bid = max(22.0, avg_prev * 0.28)
        elif contested:
            bid = max(0.58 * DAILY_SALARY, highest_prev * 0.55)
        else:
            bid = max(20.0, avg_prev * 0.22)
    else:
        if slots >= 2:
            bid = 16.0 if highest_prev >= 90 else 24.0
        else:
            bid = max(26.0, highest_prev * 0.35)

    if budget < bid:
        bid = budget

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, 63.0))

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from immediate previous_trace
    yesterday_bids = []
    yesterday_hp_after = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass
        try:
            yesterday_hp_after.append(int(prev.get('hp_after', o.get('hp', 0))))
        except Exception:
            yesterday_hp_after.append(int(o.get('hp', 0)))

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev_bid = 0.0
    if len(yesterday_bids) >= 2:
        sorted_bids = sorted(yesterday_bids, reverse=True)
        second_prev_bid = sorted_bids[1]

    # Supply pressure: moderate supply implies fewer winners; bid closer to incumbents.
    # We map supply to a multiplier.
    if supply <= MIN_SUPPLY:
        supply_mult = 1.0
    elif supply >= MAX_SUPPLY:
        supply_mult = 0.75
    else:
        # linear interpolation between 1.0 at 15 and 0.75 at 25
        supply_mult = 1.0 - 0.25 * ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))

    # Urgency based on HP/no_water_days
    urgency = 0.0
    if hp <= 2:
        urgency = 1.0
    elif hp <= 4:
        urgency = 0.7
    elif hp <= 6:
        urgency = 0.4
    else:
        urgency = 0.2

    if no_water_days >= 2:
        urgency = max(urgency, 0.8)

    # Core strategy: undercut the strongest yesterday bidder slightly,
    # but if we're very urgent, match closer.
    # Observed meta: Cindy/Eric average bids ~110; aim just below them.
    target_base = highest_prev_bid

    # If our urgency is low, underbid; if high, bid closer.
    if urgency < 0.5:
        target = target_base - 3.0
    else:
        target = target_base - 1.0

    # Add small adjustment for supply
    target = target * supply_mult

    # Ensure we don't bid too low to lose when supply is tight.
    # Use a floor tied to our urgency.
    if urgency >= 0.8:
        floor_bid = DAILY_SALARY * 0.75
    elif urgency >= 0.4:
        floor_bid = DAILY_SALARY * 0.55
    else:
        floor_bid = DAILY_SALARY * 0.45

    # If highest_prev_bid is extremely low (e.g., due to one agent dying), revert to a conservative bid.
    if highest_prev_bid < DAILY_SALARY * 0.4:
        target = max(target, floor_bid)
    else:
        target = max(target, floor_bid)

    # Cap by budget and avoid overcommitting when budget is low.
    # Also keep some buffer for later days.
    buffer_factor = 0.85 if day <= 5 else 0.95
    max_affordable = budget * buffer_factor

    bid = float(min(max_affordable, target))

    # If bid becomes non-positive due to budget, bid what we can.
    if bid <= 0.0:
        bid = float(min(budget, DAILY_SALARY * 0.3))

    return bid

